class FinancialStatement(BaseModel):
    """A condensed consolidated statement of operations for Apple Inc. for specified periods."""

    model_config = ConfigDict(graph_id_fields=["statement_title"])

    statement_title: str = Field(
        ...,
        description="The document header names the statement.",
        examples=["CONDENSED CONSOLIDATED STATEMENTS OF OPERATIONS (Unaudited)"],
    )

    company_name: Optional[str] = Field(
        None,
        description="LOOK FOR the company name at the top of the document.",
        examples=["Apple Inc."],
    )

    currency_unit: Optional[str] = Field(
        None,
        description="LOOK FOR the currency and units in the header or table note.",
        examples=["In millions"],
    )

    periods_covered: List[str] = Field(
        default_factory=list,
        description="LOOK FOR column headers indicating the periods covered.",
        examples=["Three Months Ended - June 27, 2026", "Nine Months Ended - June 27, 2026"],
    )

    has_line_item: List[LineItem] = edge(
        label="CONTAINS_LINE",
        default_factory=list,
        description="",  # TODO(docling-graph): add a 1-3 sentence LOOK-FOR description
    )

    has_segment_sales: List[SegmentSales] = edge(
        label="CONTAINS_LINE",
        default_factory=list,
        description="",  # TODO(docling-graph): add a 1-3 sentence LOOK-FOR description
    )

    has_category_sales: List[CategorySales] = edge(
        label="CONTAINS_LINE",
        default_factory=list,
        description="",  # TODO(docling-graph): add a 1-3 sentence LOOK-FOR description
    )

    @model_validator(mode="after")
    def _deduplicate_periods_covered(self) -> Self:
        """Keep first occurrence per key (removes duplicates from chunked extraction)."""
        if not self.periods_covered:
            return self
        seen: set[str] = set()
        unique: list[Any] = []
        for item in self.periods_covered:
            key = str(item).strip().lower()
            if key not in seen:
                seen.add(key)
                unique.append(item)
        object.__setattr__(self, "periods_covered", unique)
        return self

    @model_validator(mode="after")
    def _deduplicate_has_line_item(self) -> Self:
        """Keep first occurrence per key (removes duplicates from chunked extraction)."""
        if not self.has_line_item:
            return self
        seen: set[str] = set()
        unique: list[Any] = []
        for item in self.has_line_item:
            key = str(getattr(item, "name_label", "") or "").strip().lower()
            if key not in seen:
                seen.add(key)
                unique.append(item)
        object.__setattr__(self, "has_line_item", unique)
        return self

    @model_validator(mode="after")
    def _deduplicate_has_segment_sales(self) -> Self:
        """Keep first occurrence per key (removes duplicates from chunked extraction)."""
        if not self.has_segment_sales:
            return self
        seen: set[str] = set()
        unique: list[Any] = []
        for item in self.has_segment_sales:
            key = str(getattr(item, "segment_name", "") or "").strip().lower()
            if key not in seen:
                seen.add(key)
                unique.append(item)
        object.__setattr__(self, "has_segment_sales", unique)
        return self

    @model_validator(mode="after")
    def _deduplicate_has_category_sales(self) -> Self:
        """Keep first occurrence per key (removes duplicates from chunked extraction)."""
        if not self.has_category_sales:
            return self
        seen: set[str] = set()
        unique: list[Any] = []
        for item in self.has_category_sales:
            key = str(getattr(item, "category_name", "") or "").strip().lower()
            if key not in seen:
                seen.add(key)
                unique.append(item)
        object.__setattr__(self, "has_category_sales", unique)
        return self

    def __str__(self) -> str:
        parts = [self.statement_title, self.company_name]
        return " ".join(str(p) for p in parts if p) or "Unknown"


